  insert into public.quiz_sets (slug, title, description, is_active, storage_file_path)
  insert into public.lessons (set_id, lesson_num, title, source_doc) values (v_set_id, 1, 'BÀI 1. KHÁI QUÁT CHUNG VỀ HÀNG KHÔNG DÂN DỤNG QUỐC TẾ', 'Nguồn: ANSC 1.1 - Khái quát chung về HKDD quốc tế') returning id into v_l1;
  insert into public.lessons (set_id, lesson_num, title, source_doc) values (v_set_id, 2, 'BÀI 2. KHÁI QUÁT CHUNG VỀ HÀNG KHÔNG DÂN DỤNG VIỆT NAM', 'Nguồn: ANSC 1.2 - Khái quát chung về HKDD Việt Nam') returning id into v_l2;
  insert into public.lessons (set_id, lesson_num, title, source_doc) values (v_set_id, 3, 'BÀI 3. PHÁP LUẬT QUỐC TẾ VỀ HÀNG KHÔNG VÀ AN NINH HÀNG KHÔNG', 'Nguồn: ANSC 1.3 - Pháp luật quốc tế về hàng không và ANHK') returning id into v_l3;
  insert into public.lessons (set_id, lesson_num, title, source_doc) values (v_set_id, 4, 'BÀI 4. PHÁP LUẬT QUỐC GIA VỀ HÀNG KHÔNG VÀ AN NINH HÀNG KHÔNG', 'Nguồn: ANSC 1.4 - Pháp luật quốc gia về hàng không và ANHK') returning id into v_l4;
  insert into public.lessons (set_id, lesson_num, title, source_doc) values (v_set_id, 5, 'BÀI 5. KHÁI QUÁT AN TOÀN HÀNG KHÔNG; CÔNG TÁC KHẨN NGUY VÀ PHÒNG CHỐNG CHÁY NỔ', 'Nguồn: ANSC 1.5 - Khái quát An toàn hàng không; công tác khẩn nguy và phòng chống cháy nổ') returning id into v_l5;
  insert into public.lessons (set_id, lesson_num, title, source_doc) values (v_set_id, 6, 'BÀI 6. KHÁI QUÁT QUY TRÌNH VẬN CHUYỂN HÀNH KHÁCH, HÀNH LÝ, HÀNG HÓA', 'Nguồn: ANSC 1.6 - Khái quát quy trình vận chuyển hành khách, hành lý, hàng hóa') returning id into v_l6;
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l1, 1, 1, 'Mô hình “Thành phố sân bay” (Aerotropolis) có đặc điểm gì?', '{"A": "Sân bay là trung tâm, xung quanh phát triển khu công nghiệp và đô thị", "B": "Sân bay chỉ phục vụ hành khách", "C": "Sân bay chỉ phục vụ quân sự", "D": "Sân bay nằm tách biệt khỏi đô thị"}'::jsonb, 'A', 'Sân bay là trung tâm, xung quanh phát triển khu công nghiệp và đô thị', 'Tài liệu mô tả mô hình Aerotropolis là mô hình lấy sân bay làm trung tâm, xung quanh phát triển khu công nghiệp công nghệ cao, trung tâm hội nghị và đô thị thương mại.', 'ANSC 1.1, trang 15: “Mô hình "Thành phố sân bay" (Aerotropolis) trong đó sân bay trở thành trung tâm, xung quanh là các khu công nghiệp công nghệ cao, trung tâm hội nghị và đô thị thương mại.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l1, 1, 2, 'Đặc điểm nổi bật của ngành hàng không dân dụng quốc tế là gì?', '{"A": "Áp dụng khoa học công nghệ hiện đại, vốn lớn, hoạt động toàn cầu", "B": "Chỉ phục vụ nội địa, vốn nhỏ", "C": "Chủ yếu dựa vào lao động phổ thông", "D": "Không liên quan đến nghiên cứu và đào tạo"}'::jsonb, 'A', 'Áp dụng khoa học công nghệ hiện đại, vốn lớn, hoạt động toàn cầu', 'Đặc điểm của ngành HKDD được nêu: áp dụng khoa học, công nghệ hiện đại, quy mô vốn lớn, hoạt động cả trong và ngoài nước, gắn kết với đào tạo, nghiên cứu.', 'ANSC 1.1, trang 16: “Ngành HKDD là một ngành áp dụng khoa học, công nghệ kỹ thuật hiện đại, trình độ quản lý tiên tiến, có quy mô lớn về vốn lớn, hoạt động cả trong và ngoài nước, có sự gắn kết chặt chẽ giữa khoa học công nghệ, đào tạo, nghiên cứu triển khai với sản xuất kinh doanh.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l1, 1, 3, 'Công ước nào năm 1944 đã định hình toàn bộ luật hàng không quốc tế và khẳng định chủ quyền không lưu của mỗi quốc gia?', '{"A": "Công ước Warsaw", "B": "Công ước Paris", "C": "Công ước Chicago", "D": "Công ước Geneva"}'::jsonb, 'C', 'Công ước Chicago', 'Công ước Chicago 1944 được tài liệu khẳng định là văn kiện định hình toàn bộ luật hàng không quốc tế và khẳng định chủ quyền không lưu của mỗi quốc gia.', 'ANSC 1.1, trang 16–17: “Công ước Chicago 1944: Định hình toàn bộ luật hàng không quốc tế; khẳng định chủ quyền không lưu của mỗi quốc gia; thiết lập các tiêu chuẩn an ninh và an toàn bay.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l1, 1, 4, 'Tổ chức nào thuộc Liên Hợp Quốc ban hành các Phụ lục (Annexes) quy định tiêu chuẩn kỹ thuật bắt buộc các quốc gia thành viên tuân thủ?', '{"A": "IATA", "B": "ICAO", "C": "CAA", "D": "FAA"}'::jsonb, 'B', 'ICAO', 'ICAO là cơ quan thuộc Liên Hợp Quốc, ban hành các Phụ lục (Annexes) chứa tiêu chuẩn kỹ thuật (SARPs) mà các quốc gia thành viên phải tuân thủ. IATA là hiệp hội của các hãng hàng không.', 'ANSC 1.1, trang 17: “Tổ chức Hàng không dân dụng quốc tế (ICAO) là cơ quan thuộc Liên Hợp Quốc, ban hành các Phụ lục (Annexes) quy định tiêu chuẩn kỹ thuật (SARPs) bắt buộc các quốc gia thành viên tuân thủ.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l1, 1, 5, 'Các nhà sản xuất máy bay lớn thống trị toàn cầu trong phân khúc máy bay thân rộng/thân hẹp là ai?', '{"A": "Embraer và COMAC", "B": "Boeing và Airbus", "C": "Vietjet và Vietnam Airlines", "D": "SkyTeam và Oneworld"}'::jsonb, 'B', 'Boeing và Airbus', 'Boeing và Airbus thống trị phân khúc thân rộng/thân hẹp; Embraer, COMAC chỉ là các hãng máy bay khu vực.', 'ANSC 1.1, trang 17: “Các nhà sản xuất tàu bay lớn hiện gồm Boeing và Airbus thống trị toàn cầu trong phân khúc máy bay thân rộng/thân hẹp, cùng các hãng máy bay khu vực như Embraer, COMAC.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l1, 1, 6, 'Quản lý điều hành bay (Air Traffic Management - ATM) bao gồm những dịch vụ nào?', '{"A": "Kiểm soát tại sân bay, kiểm soát tiếp cận, kiểm soát đường dài", "B": "Kiểm soát giá vé, kiểm soát hành lý, kiểm soát suất ăn", "C": "Kiểm soát du lịch, kiểm soát khách sạn, kiểm soát hải quan", "D": "Kiểm soát tài chính, kiểm soát ngân hàng, kiểm soát đầu tư"}'::jsonb, 'A', 'Kiểm soát tại sân bay, kiểm soát tiếp cận, kiểm soát đường dài', 'Dịch vụ không lưu (ATS) trong ATM gồm ba loại kiểm soát: tại sân bay (Tower), tiếp cận (Approach) và đường dài (ACC).', 'ANSC 1.1, trang 17: “Quản lý điều hành bay (Air Traffic Management - ATM)… trong đó dịch vụ không lưu (ATS) bao gồm kiểm soát tại sân bay (Tower), kiểm soát tiếp cận (Approach) và kiểm soát đường dài (Area Control - ACC).”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l1, 1, 7, 'ICAO ban hành các tiêu chuẩn và khuyến nghị thực hành (SARPs) nhằm mục đích gì?', '{"A": "Tăng doanh thu cho các hãng hàng không", "B": "Thống nhất luật lệ hàng không quốc tế", "C": "Giảm giá vé máy bay", "D": "Quản lý du lịch quốc tế"}'::jsonb, 'B', 'Thống nhất luật lệ hàng không quốc tế', 'Mục đích ICAO ban hành SARPs là để các quốc gia thành viên áp dụng, tạo sự thống nhất trong luật lệ hàng không quốc tế.', 'ANSC 1.1, trang 18: “ICAO ban hành các tiêu chuẩn và khuyến nghị thực hành (Standards and Recommended Practices - SARPs)… để các quốc gia thành viên áp dụng, tạo sự thống nhất trong luật lệ hàng không quốc tế.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l1, 1, 8, 'Đại hội đồng (Assembly) của ICAO họp định kỳ bao lâu một lần?', '{"A": "Hằng năm", "B": "2 năm một lần", "C": "3 năm một lần", "D": "5 năm một lần"}'::jsonb, 'C', '3 năm một lần', 'Đại hội đồng là cơ quan quyền lực cao nhất của ICAO, họp 3 năm một lần.', 'ANSC 1.1, trang 19: “Đại Hội đồng họp 3 năm một lần để quyết định chính sách tổng thể, ngân sách và bầu Hội đồng.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l1, 1, 9, 'Ủy ban Hàng không (Air Navigation Commission - ANC) có bao nhiêu thành viên chính thức?', '{"A": "10", "B": "19", "C": "36", "D": "50"}'::jsonb, 'B', '19', 'Ủy ban Hàng không (ANC) có 19 thành viên là các chuyên gia kỹ thuật. (Con số 36 là số thành viên Hội đồng ICAO.)', 'ANSC 1.1, trang 19: “Ủy ban có 19 thành viên là các chuyên gia kỹ thuật, được các quốc gia thành viên ICAO đề cử và Hội đồng bổ nhiệm.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l1, 1, 10, 'Công ước nào do Ủy ban Pháp luật (Legal Committee) xây dựng liên quan đến trách nhiệm vận chuyển quốc tế?', '{"A": "Công ước Tokyo 1963", "B": "Công ước Hague 1970", "C": "Công ước Montreal 1999", "D": "Công ước Chicago 1944"}'::jsonb, 'C', 'Công ước Montreal 1999', 'Trong các ví dụ về công ước do Ủy ban Pháp luật xây dựng, Công ước Montreal 1999 là công ước về trách nhiệm vận chuyển quốc tế.', 'ANSC 1.1, trang 20: “Ví dụ: Công ước Tokyo 1963 (hành vi vi phạm trên máy bay), Công ước Montreal 1999 (trách nhiệm vận chuyển quốc tế), Công ước Hague 1970 (chống chiếm đoạt máy bay).”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l1, 1, 11, 'ICAO hiện có bao nhiêu văn phòng khu vực trên thế giới?', '{"A": "5", "B": "6", "C": "7", "D": "8"}'::jsonb, 'C', '7', 'Tài liệu ghi ICAO có 7 văn phòng khu vực. (Lưu ý: tài liệu chỉ liệt kê tên 6 nơi.)', 'ANSC 1.1, trang 22: “ICAO có 7 văn phòng khu vực đặt tại Bangkok (Châu Á – Thái Bình Dương), Nairobi (Đông & Nam Phi), Paris (Châu Âu & Bắc Đại Tây Dương), Cairo (Trung Đông), Mexico City (Bắc Mỹ, Trung Mỹ & Caribbean), Lima (Nam Mỹ).”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l1, 1, 12, 'Ủy ban Hàng không (Air Navigation Commission - ANC) của ICAO có đặc điểm nào sau đây?', '{"A": "Thành viên đại diện cho quốc gia và bỏ phiếu theo lợi ích quốc gia", "B": "Hoạt động độc lập dựa trên chuyên môn, không đại diện cho quốc gia", "C": "Chỉ xem xét các vấn đề pháp lý liên quan đến hàng không", "D": "Là cơ quan thường trực của Đại hội đồng"}'::jsonb, 'B', 'Hoạt động độc lập dựa trên chuyên môn, không đại diện cho quốc gia', 'Các ủy viên ANC hoạt động độc lập dựa trên chuyên môn, không đại diện cho quốc gia. Các vấn đề pháp lý thuộc Ủy ban Pháp luật; cơ quan thường trực là Hội đồng.', 'ANSC 1.1, trang 19: “Các ủy viên không đại diện cho quốc gia mà hoạt động độc lập, dựa trên chuyên môn hàng không.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l1, 1, 13, 'Chương trình CORSIA do ICAO đề ra nhằm mục tiêu gì?', '{"A": "Tăng cường an ninh hàng không quốc tế", "B": "Giảm thiểu khí thải CO₂ trong ngành hàng không", "C": "Chuẩn hóa quy trình xuất nhập cảnh", "D": "Phát triển hạ tầng sân bay toàn cầu"}'::jsonb, 'B', 'Giảm thiểu khí thải CO₂ trong ngành hàng không', 'CORSIA được tài liệu nêu là chương trình giảm khí thải CO₂ trong định hướng phát triển bền vững của ICAO.', 'ANSC 1.1, trang 19: “Đưa ra chiến lược toàn cầu về hàng không xanh, giảm thiểu tác động môi trường. Đề ra chương trình giảm khí thải CO₂ (như CORSIA).”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l1, 1, 14, 'Ủy ban Pháp luật (Legal Committee) của ICAO đã xây dựng Công ước nào sau đây liên quan đến hành vi vi phạm trên máy bay?', '{"A": "Công ước Montreal 1999", "B": "Công ước Tokyo 1963", "C": "Công ước Hague 1970", "D": "Công ước Chicago 1944"}'::jsonb, 'B', 'Công ước Tokyo 1963', 'Công ước Tokyo 1963 là công ước về hành vi vi phạm trên máy bay (Montreal 1999 là trách nhiệm vận chuyển; Hague 1970 là chống chiếm đoạt máy bay).', 'ANSC 1.1, trang 20: “Công ước Tokyo 1963 (hành vi vi phạm trên máy bay).”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l1, 1, 15, 'Tổ chức nào được thành lập năm 1996, đại diện cho tiếng nói toàn cầu của quản lý không lưu (ATM)?', '{"A": "IATA", "B": "ACI", "C": "ICAO", "D": "CANSO"}'::jsonb, 'D', 'CANSO', 'CANSO là tiếng nói toàn cầu của quản lý không lưu (ATM), thành lập năm 1996. ACI thành lập năm 1991, đại diện cho các sân bay.', 'ANSC 1.1, trang 24–25: “CANSO là tiếng nói toàn cầu của quản lý không lưu (Air Traffic Management - ATM) trên toàn thế giới. … CANSO được thành lập vào năm 1996.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l2, 2, 1, 'Thực thể nào sau đây giữ vai trò là Nhà chức trách hàng không dân dụng tại Việt Nam?', '{"A": "Bộ Xây dựng.", "B": "Tổng công ty Cảng hàng không Việt Nam (ACV).", "C": "Cục Hàng không Việt Nam (CAAV).", "D": "Tổng công ty Quản lý bay Việt Nam (VATM)."}'::jsonb, 'C', 'Cục Hàng không Việt Nam (CAAV).', 'Cục Hàng không Việt Nam (CAAV) là nhà chức trách hàng không, thực thi chức năng quản lý nhà nước chuyên trách. ACV và VATM là doanh nghiệp.', 'ANSC 1.2, trang 18: “Cục Hàng không Việt Nam – CAAV là nhà chức trách hàng không là cơ quan thực thi chức năng quản lý nhà nước chuyên trách.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l2, 2, 2, 'Vùng thông báo bay (FIR) do ICAO giao cho Việt Nam quản lý hiện nay bao gồm những vùng nào?', '{"A": "FIR Hà Nội và FIR Đà Nẵng.", "B": "FIR Hà Nội và FIR Hồ Chí Minh.", "C": "FIR Bắc Bộ và FIR Nam Bộ.", "D": "FIR Nội Bài và FIR Tân Sơn Nhất."}'::jsonb, 'B', 'FIR Hà Nội và FIR Hồ Chí Minh.', 'Việt Nam đang điều hành hai vùng thông báo bay do ICAO giao: FIR Hà Nội và FIR Hồ Chí Minh.', 'ANSC 1.2, trang 9, 20: “Hiện nay HKDD Việt Nam đang điều hành hai vùng thông báo bay (FIR Hồ Chí Minh và FIR Hà Nội)… do ICAO giao Việt Nam quản lý.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l2, 2, 3, 'Bộ phận nào điều hành trực tiếp máy bay trong quá trình chạy đà cất cánh và xả đà hạ cánh trên đường băng?', '{"A": "Trung tâm kiểm soát đường dài (ACC).", "B": "Trạm kiểm soát tiếp cận (APP).", "C": "Đài kiểm soát tại sân (TWR - Tower).", "D": "Trung tâm điều hành khai thác của Hãng hàng không (OCC)."}'::jsonb, 'C', 'Đài kiểm soát tại sân (TWR - Tower).', 'Đài kiểm soát tại sân (TWR) điều hành máy bay trong giai đoạn cất cánh, hạ cánh trên sân bay. APP điều hành giai đoạn lấy/hạ độ cao; ACC điều hành ở độ cao hành trình.', 'ANSC 1.2, trang 20: “Đài kiểm soát tại sân (TWR - Tower) có trách nhiệm điều hành máy bay nổ máy, lăn, cất cánh, hạ cánh và di chuyển trong khu vực sân đỗ.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l2, 2, 4, 'Chuyến bay nội địa đầu tiên của Hàng không Việt Nam được khai trương vào thời điểm nào?', '{"A": "Tháng 9 năm 1956", "B": "Tháng 5 năm 1959", "C": "Tháng 6 năm 1963", "D": "Tháng 2 năm 1964"}'::jsonb, 'A', 'Tháng 9 năm 1956', 'Chuyến bay nội địa đầu tiên khai trương vào tháng 9/1956.', 'ANSC 1.2, trang 3: “Chuyến bay nội địa đầu tiên được khai trương vào tháng 9 năm 1956.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l2, 2, 5, 'Việt Nam chính thức trở thành thành viên của ICAO vào ngày nào?', '{"A": "12/4/1980", "B": "25/02/1980", "C": "1/3/1980", "D": "7/12/1944"}'::jsonb, 'A', '12/4/1980', 'Ngày 25/02/1980 ký Giấy gia nhập; ngày 1/3/1980 gửi công hàm; Việt Nam chính thức là thành viên ICAO ngày 12/4/1980.', 'ANSC 1.2, trang 5, 6: “Hàng không dân dụng Việt Nam đã chính thức trở thành thành viên của Tổ chức hàng không dân dụng quốc tế (ICAO) ngày 12/4/1980.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l2, 2, 6, 'Tổng cục Hàng không dân dụng Việt Nam được thành lập theo Quyết định số 28/CP vào ngày nào?', '{"A": "11/02/1976", "B": "22/08/1989", "C": "30/07/1992", "D": "06/10/2015"}'::jsonb, 'A', '11/02/1976', 'Quyết định số 28/CP thành lập Tổng cục HKDD được ban hành ngày 11/2/1976.', 'ANSC 1.2, trang 6: “Ngày 11/2/1976, Thủ tướng ban hành Quyết định số 28/CP thành lập Tổng cục HKDD trực thuộc Hội đồng Chính phủ.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l2, 2, 7, 'Hãng hàng không quốc gia Vietnam Airlines được thành lập vào thời điểm nào?', '{"A": "Tháng 4 năm 1993", "B": "Tháng 12 năm 1991", "C": "Tháng 8 năm 1989", "D": "Tháng 6 năm 1976"}'::jsonb, 'A', 'Tháng 4 năm 1993', 'Hãng hàng không quốc gia Vietnam Airlines được Chính phủ thành lập tháng 4/1993.', 'ANSC 1.2, trang 6: “Tháng 4 năm 1993, Chính phủ đã thành lập Hãng hàng không quốc gia (Vietnamairlines).”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l2, 2, 8, 'Việt Nam chính thức tiếp nhận quyền kiểm soát phần phía Nam vùng FIR Hồ Chí Minh vào ngày nào?', '{"A": "08/12/1994", "B": "12/04/1980", "C": "29/06/2006", "D": "10/06/2010"}'::jsonb, 'A', '08/12/1994', 'Việt Nam chính thức tiếp nhận quyền kiểm soát phần phía Nam FIR Hồ Chí Minh từ ngày 08/12/1994.', 'ANSC 1.2, trang 7: “Hàng không dân dụng Việt Nam đã chính thức tiếp nhận thực hiện quyền kiểm soát phần phía Nam vùng thông báo bay (FIR) Hồ Chí Minh từ ngày 08 tháng 12 năm 1994.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l2, 2, 9, 'Vietnam Airlines trở thành thành viên Liên minh hàng không SkyTeam vào thời điểm nào?', '{"A": "10/06/2010", "B": "01/04/2015", "C": "06/10/2015", "D": "29/06/2006"}'::jsonb, 'A', '10/06/2010', 'Vietnam Airlines trở thành thành viên SkyTeam ngày 10/6/2010 (01/4/2015 là mốc chuyển sang công ty cổ phần).', 'ANSC 1.2, trang 8: “Vietnam Airlines… trở thành hãng hàng không duy nhất của ASEAN là thành viên Liên minh hàng không SkyTeam (10/6/2010).”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l2, 2, 10, 'Việc Việt Nam gia nhập Công ước Chicago năm 1980 có ý nghĩa gì đối với ngành Hàng không dân dụng Việt Nam?', '{"A": "Đánh dấu hàng không Việt Nam chính thức hội nhập với cộng đồng hàng không quốc tế", "B": "Giúp Việt Nam mở đường bay đầu tiên ra nước ngoài", "C": "Cho phép Việt Nam mua máy bay từ Liên Xô", "D": "Là cơ sở thành lập Vietnam Airlines"}'::jsonb, 'A', 'Đánh dấu hàng không Việt Nam chính thức hội nhập với cộng đồng hàng không quốc tế', 'Việc gia nhập Công ước Chicago và ICAO năm 1980 được tài liệu đánh giá là mốc hàng không Việt Nam chính thức hội nhập quốc tế.', 'ANSC 1.2, trang 5: “Đây là một mốc quan đánh dấu hàng không Việt Nam chính thức hội nhập với cộng đồng hàng không quốc tế và thế giới.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l2, 2, 11, 'Trong giai đoạn 1965–1975, Hàng không dân dụng Việt Nam vừa thực hiện nhiệm vụ quân sự vừa dân dụng. Điều này thể hiện đặc điểm gì của ngành trong thời kỳ chiến tranh?', '{"A": "Kết hợp chặt chẽ giữa quốc phòng và kinh tế", "B": "Tập trung hoàn toàn vào vận tải dân dụng", "C": "Chỉ phục vụ vận chuyển hàng hóa quốc tế", "D": "Hoạt động độc lập với Bộ Quốc phòng"}'::jsonb, 'A', 'Kết hợp chặt chẽ giữa quốc phòng và kinh tế', 'Trong thời chiến, Bộ Quốc phòng đồng thời thực hiện chức năng quốc phòng, quản lý nhà nước và kinh doanh vận tải; không quân vận tải vừa làm nhiệm vụ quân sự vừa bay dân dụng, thể hiện sự kết hợp quốc phòng với kinh tế.', 'ANSC 1.2, trang 3: “Bộ Quốc phòng thực hiện đồng thời ba chức năng: Quốc phòng, quản lý nhà nước và kinh doanh vận tải hàng không. … không quân vận tải vừa làm nhiệm vụ quân sự, vừa làm nhiệm vụ bay dân dụng.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l2, 2, 12, 'Việc tiếp nhận quyền kiểm soát vùng FIR Hồ Chí Minh năm 1994 thể hiện điều gì về năng lực của Hàng không Việt Nam?', '{"A": "Đủ khả năng quản lý, điều hành vùng trời quốc gia theo tiêu chuẩn quốc tế", "B": "Bắt đầu khai thác đường bay quốc tế đầu tiên", "C": "Hoàn tất cổ phần hóa Vietnam Airlines", "D": "Gia nhập Liên minh SkyTeam"}'::jsonb, 'A', 'Đủ khả năng quản lý, điều hành vùng trời quốc gia theo tiêu chuẩn quốc tế', 'Sau khi tiếp nhận FIR Hồ Chí Minh, Việt Nam đã tự quản lý, điều hành hàng triệu chuyến bay an toàn và được ICAO tin cậy, thể hiện năng lực quản lý vùng trời theo chuẩn quốc tế.', 'ANSC 1.2, trang 7: “Từ đó đến nay, Hàng không Việt Nam đã quản lý, điều hành, chỉ huy hàng triệu chuyến bay trong nước và quốc tế tuyệt đối an toàn, được các hãng hàng không nước ngoài và tổ chức hàng không dân dụng Quốc tế tin cậy.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l2, 2, 13, 'Sự kiện Vietnam Airlines trở thành thành viên Liên minh SkyTeam năm 2010 phản ánh điều gì về vị thế của ngành hàng không Việt Nam?', '{"A": "Khẳng định sự lớn mạnh và hội nhập quốc tế sâu rộng của hàng không Việt Nam", "B": "Đánh dấu việc tách khỏi Bộ Quốc phòng", "C": "Là bước đầu cổ phần hóa Vietnam Airlines", "D": "Là thời điểm Việt Nam mở đường bay Long Thành"}'::jsonb, 'A', 'Khẳng định sự lớn mạnh và hội nhập quốc tế sâu rộng của hàng không Việt Nam', 'Việc gia nhập SkyTeam được tài liệu đánh giá là bước phát triển vượt bậc trong hội nhập quốc tế và thể hiện sự lớn mạnh của hàng không Việt Nam.', 'ANSC 1.2, trang 8: “…thành viên Liên minh hàng không SkyTeam (10/6/2010) đã đánh dấu bước phát triển vượt bậc của ngành hàng không Việt Nam trong tiến trình hội nhập quốc tế, sự lớn mạnh của Hãng Hàng không Việt Nam.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l2, 2, 14, 'Các cảng hàng không quốc tế nào hiện nay được coi là trung tâm giao thương, du lịch và đầu tư?', '{"A": "Nội Bài, Tân Sơn Nhất, Đà Nẵng, Cam Ranh, Phú Quốc", "B": "Vinh, Chu Lai, Pleiku, Cà Mau", "C": "Đồng Hới, Rạch Giá, Côn Đảo, Tuy Hòa", "D": "Điện Biên, Thọ Xuân, Phù Cát, Liên Khương"}'::jsonb, 'A', 'Nội Bài, Tân Sơn Nhất, Đà Nẵng, Cam Ranh, Phú Quốc', 'Tài liệu nêu đích danh 5 cảng HKQT Nội Bài, Tân Sơn Nhất, Đà Nẵng, Cam Ranh, Phú Quốc là trung tâm giao thương, du lịch và đầu tư.', 'ANSC 1.2, trang 10: “Các cảng hàng không quốc tế như Nội Bài, Tân Sơn Nhất, Đà Nẵng, Cam Ranh, Phú Quốc, và sắp tới là Long Thành, là trung tâm giao thương, du lịch và đầu tư.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l2, 2, 15, 'Hàng không dân dụng Việt Nam đóng góp trực tiếp vào GDP thông qua hoạt động nào?', '{"A": "Xây dựng hạ tầng cảng biển", "B": "Vận tải hành khách và hàng hóa", "C": "Khai thác khoáng sản", "D": "Phát triển nông nghiệp"}'::jsonb, 'B', 'Vận tải hành khách và hàng hóa', 'HKDD Việt Nam đóng góp trực tiếp vào GDP thông qua vận tải hành khách và hàng hóa.', 'ANSC 1.2, trang 10: “Đối với kinh tế ngành HKDD Việt nam đóng góp trực tiếp vào GDP thông qua vận tải hành khách và hàng hóa.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l3, 3, 1, 'Công ước Chicago được ký kết vào ngày nào?', '{"A": "7/12/1944", "B": "13/10/1919", "C": "20/2/1928", "D": "4/4/1947"}'::jsonb, 'A', '7/12/1944', 'Công ước Chicago được 52 quốc gia ký ngày 7/12/1944 và có hiệu lực ngày 4/4/1947. (13/10/1919 là Công ước Paris; 20/2/1928 là Công ước Havana.)', 'ANSC 1.3, trang 18: “…được 52 quốc gia ký kết vào cuối Hội nghị Chicago tại Phòng khiêu vũ lớn của khách sạn Stevens, ngày 7 tháng 12 năm 1944 và có hiệu lực vào ngày 4 tháng 4 năm 1947.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l3, 3, 2, 'Tàu bay dân dụng muốn bay qua lãnh thổ quốc gia khác phải có gì?', '{"A": "Sự cho phép đặc biệt", "B": "Giấy phép thương mại", "C": "Giấy chứng nhận khả năng bay", "D": "Giấy phép nhân viên"}'::jsonb, 'A', 'Sự cho phép đặc biệt', 'Theo Chương 1 Công ước Chicago, tàu bay dân dụng muốn bay qua lãnh thổ quốc gia khác phải có sự cho phép đặc biệt.', 'ANSC 1.3, trang 19: “Tàu bay dân dụng của quốc gia này muốn bay qua lãnh thổ quốc gia khác phải có sự cho phép đặc biệt.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l3, 3, 3, 'Quốc tịch tàu bay được xác định dựa trên yếu tố nào?', '{"A": "Quốc gia nơi tàu bay được đăng ký", "B": "Quốc gia sản xuất tàu bay", "C": "Quốc gia khai thác tàu bay", "D": "Quốc gia cấp giấy phép phi công"}'::jsonb, 'A', 'Quốc gia nơi tàu bay được đăng ký', 'Điều 17: tàu bay mang quốc tịch của quốc gia nơi đăng ký.', 'ANSC 1.3, trang 19: “Điều 17 quy định tàu bay mang quốc tịch của quốc gia nơi nó được đăng ký.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l3, 3, 4, 'Mỗi tàu bay phải mang theo giấy chứng nhận gì để chứng minh đủ điều kiện kỹ thuật?', '{"A": "Giấy chứng nhận khả năng bay", "B": "Giấy phép nhân viên", "C": "Giấy chứng nhận đăng ký", "D": "Nhật ký bay"}'::jsonb, 'A', 'Giấy chứng nhận khả năng bay', 'Điều 29, 31: tàu bay phải mang chứng chỉ đủ điều kiện bay (giấy chứng nhận khả năng bay) do quốc gia đăng ký cấp.', 'ANSC 1.3, trang 20: “Điều 31 quy định mọi tàu bay quốc tế phải có chứng chỉ đủ điều kiện bay do quốc gia đăng ký cấp.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l3, 3, 5, 'Vật tư tàu bay như nhiên liệu, dầu, phụ tùng khi nhập cảnh được hưởng ưu đãi gì?', '{"A": "Miễn thuế hải quan", "B": "Giảm 50% thuế", "C": "Được bán tại quốc gia sở tại", "D": "Được chuyển nhượng tự do"}'::jsonb, 'A', 'Miễn thuế hải quan', 'Điều 24: tàu bay, nhiên liệu, phụ tùng, thiết bị mang theo được miễn thuế hải quan (khi chỉ quá cảnh hoặc tạm dừng, trừ khi bốc dỡ).', 'ANSC 1.3, trang 20: “Điều 24 quy định tàu bay, nhiên liệu, phụ tùng, thiết bị và thực phẩm mang theo được miễn thuế hải quan khi chỉ quá cảnh hoặc tạm dừng, trừ khi bốc dỡ.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l3, 3, 6, 'Quốc gia nơi xảy ra tai nạn hàng không dân dụng quốc tế có trách nhiệm gì?', '{"A": "Tiến hành điều tra", "B": "Chỉ báo cáo cho ICAO", "C": "Chỉ cứu hộ hành khách", "D": "Không có trách nhiệm"}'::jsonb, 'A', 'Tiến hành điều tra', 'Điều 26: quốc gia nơi xảy ra tai nạn phải mở điều tra, cho phép quốc gia đăng ký tàu bay tham gia giám sát và báo cáo kết quả.', 'ANSC 1.3, trang 20: “Điều 26 quy định quốc gia nơi xảy ra tai nạn phải mở điều tra và cho phép quốc gia đăng ký tàu bay tham gia giám sát, đồng thời báo cáo kết quả.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l3, 3, 7, 'Các chuyến bay thương mại thường lệ quốc tế chỉ được thực hiện khi nào?', '{"A": "Có sự thỏa thuận hoặc cho phép của quốc gia sở tại", "B": "Có giấy phép phi công", "C": "Có giấy chứng nhận khả năng bay", "D": "Có sự đồng ý của ICAO"}'::jsonb, 'A', 'Có sự thỏa thuận hoặc cho phép của quốc gia sở tại', 'Điều 6: chuyến bay quốc tế thường lệ chỉ được thực hiện khi có sự cho phép đặc biệt của quốc gia sở tại.', 'ANSC 1.3, trang 19: “Điều 6 quy định các chuyến bay quốc tế thường lệ chỉ được thực hiện khi có sự cho phép đặc biệt của quốc gia sở tại.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l3, 3, 8, 'Quốc gia thành viên phải công bố quy định và thông tin liên quan đến hàng không cho ai?', '{"A": "ICAO", "B": "Liên Hợp Quốc", "C": "Hội Quốc Liên", "D": "Tòa án Công lý Quốc tế"}'::jsonb, 'A', 'ICAO', 'Các quốc gia thành viên có nghĩa vụ thông báo, cung cấp thông tin cho ICAO (Điều 9 – khu vực cấm bay; Điều 21 – thông tin đăng ký; Điều 38 – sự khác biệt so với tiêu chuẩn quốc tế).', 'ANSC 1.3, trang 19–21: “Điều 38 quy định nếu quốc gia không thể tuân thủ hoặc có quy định khác, phải thông báo ngay cho ICAO. ICAO sẽ thông báo sự khác biệt này cho các quốc gia khác.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l3, 3, 9, 'Công ước Chicago không áp dụng cho loại tàu bay nào?', '{"A": "Tàu bay quân sự, hải quan, cảnh sát", "B": "Tàu bay dân dụng", "C": "Tàu bay thương mại", "D": "Tàu bay chở hàng hóa"}'::jsonb, 'A', 'Tàu bay quân sự, hải quan, cảnh sát', 'Điều 3: Công ước áp dụng cho tàu bay dân dụng, không áp dụng cho tàu bay nhà nước (quân sự, hải quan, cảnh sát).', 'ANSC 1.3, trang 19: “Phân loại tàu bay (Điều 3) áp dụng cho tàu bay dân dụng, không áp dụng cho tàu bay nhà nước bao gồm tàu bay quân sự, hải quan, cảnh sát.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l3, 3, 10, 'Bản gốc Công ước Chicago được lưu giữ tại đâu?', '{"A": "Chính phủ Hoa Kỳ", "B": "Liên Hợp Quốc", "C": "ICAO", "D": "Paris, Pháp"}'::jsonb, 'A', 'Chính phủ Hoa Kỳ', 'Điều 91: Chính phủ Hoa Kỳ là cơ quan lưu trữ Công ước và thông báo cho các quốc gia.', 'ANSC 1.3, trang 26: “Chính phủ Hoa Kỳ là cơ quan lưu trữ và thông báo cho các quốc gia.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l3, 3, 11, 'Việc ICAO ban hành và điều chỉnh các tiêu chuẩn quốc tế (SARPs) có ý nghĩa gì?', '{"A": "Giúp thống nhất quy định toàn cầu, giảm sự khác biệt giữa các quốc gia", "B": "Cho phép mỗi quốc gia tự đặt tiêu chuẩn riêng", "C": "Chỉ áp dụng cho các chuyến bay nội địa", "D": "Loại bỏ vai trò của quốc gia sở tại"}'::jsonb, 'A', 'Giúp thống nhất quy định toàn cầu, giảm sự khác biệt giữa các quốc gia', 'Chương 6 quy định việc ban hành, áp dụng tiêu chuẩn quốc tế nhằm bảo đảm sự thống nhất; các quốc gia cam kết phối hợp để thống nhất quy định.', 'ANSC 1.3, trang 21: “Chương 6 quy định về việc ban hành, áp dụng và công nhận các tiêu chuẩn quốc tế trong hàng không dân dụng, nhằm đảm bảo sự thống nhất và an toàn. … Các quốc gia ký kết cam kết phối hợp để thống nhất quy định.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l3, 3, 12, 'Phụ lục nào liên quan đến An ninh hàng không dân dụng quốc tế chống lại các hành vi can thiệp bất hợp pháp?', '{"A": "Phụ lục 17", "B": "Phụ lục 6", "C": "Phụ lục 8", "D": "Phụ lục 12"}'::jsonb, 'A', 'Phụ lục 17', 'Phụ lục 17 – An ninh: Bảo vệ hàng không dân dụng quốc tế chống lại các hành vi can thiệp bất hợp pháp.', 'ANSC 1.3, trang 28, 33: “Phụ lục 17 của ICAO—An ninh—Bảo vệ Hàng không dân dụng quốc tế chống lại các hành vi can thiệp bất hợp pháp có hiệu lực vào năm 1975.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l3, 3, 13, 'Phụ lục nào được ICAO thông qua năm 1984 về vận chuyển an toàn hàng hóa nguy hiểm bằng đường hàng không?', '{"A": "Phụ lục 18", "B": "Phụ lục 19", "C": "Phụ lục 7", "D": "Phụ lục 5"}'::jsonb, 'A', 'Phụ lục 18', 'Năm 1984 ICAO thông qua Phụ lục 18 về vận chuyển an toàn hàng hóa nguy hiểm. (Phụ lục 19 – Quản lý an toàn, năm 2013.)', 'ANSC 1.3, trang 28: “Năm 1984 Phụ lục 18 về vận chuyển an toàn hàng hóa nguy hiểm bằng đường hàng không được ICAO thông qua.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l3, 3, 14, 'Sau sự kiện 11/9, biện pháp nào được áp dụng để tăng cường an ninh buồng lái?', '{"A": "Gia cố cửa buồng lái", "B": "Cho phép mở cửa tự do", "C": "Loại bỏ cửa buồng lái", "D": "Không có thay đổi"}'::jsonb, 'A', 'Gia cố cửa buồng lái', 'Sau sự kiện 11/9, các chính phủ gia cố cửa buồng lái, hạn chế vật dụng xách tay và mở rộng kiểm tra soi chiếu.', 'ANSC 1.3, trang 31: “Các chính phủ đã thực hiện việc gia cố cửa buồng lái, hạn chế nghiêm ngặt các vật dụng xách tay…”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l3, 3, 15, 'Người khai thác tàu bay thương mại phải thiết lập chương trình an ninh của mình nhằm mục đích gì?', '{"A": "Đáp ứng yêu cầu của chương trình an ninh hàng không dân dụng quốc gia", "B": "Giảm chi phí vận hành", "C": "Tăng lợi nhuận kinh doanh", "D": "Loại bỏ trách nhiệm pháp lý"}'::jsonb, 'A', 'Đáp ứng yêu cầu của chương trình an ninh hàng không dân dụng quốc gia', 'Theo Phụ lục 17, hãng hàng không phải thiết lập chương trình an ninh của người khai thác đáp ứng yêu cầu của chương trình an ninh HKDD quốc gia.', 'ANSC 1.3, trang 36: “Người khai thác tàu bay vận chuyển hàng không thương mại (hãng hàng không) phải thiết lập, thực hiện và duy trì một chương trình an ninh của người khai thác tàu bay đáp ứng các yêu cầu của chương trình an ninh hàng không dân dụng quốc gia.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l4, 4, 1, 'Luật Hàng không dân dụng Việt Nam năm 2026 được Quốc hội thông qua vào ngày nào?', '{"A": "10/12/2025", "B": "01/07/2026", "C": "15/12/2025", "D": "01/01/2026"}'::jsonb, 'A', '10/12/2025', 'Luật HKDD Việt Nam năm 2026 (Luật số 130/2025/QH15) được Quốc hội thông qua ngày 10/12/2025. (Lưu ý: tr. 18 của tài liệu ghi "ngày 15 tháng 12 năm 2025"; đáp án đã được xác nhận là A.)', 'ANSC 1.4, trang 4: “Luật Hàng không dân dụng Việt Nam năm 2026 (Luật số 130/2025/QH15) được Quốc hội thông qua ngày 10/12/2025 và chính thức có hiệu lực từ ngày 01/07/2026.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l4, 4, 2, 'Luật Hàng không dân dụng Việt Nam năm 2026 có hiệu lực từ ngày nào?', '{"A": "01/07/2026", "B": "10/12/2025", "C": "01/01/2026", "D": "15/07/2026"}'::jsonb, 'A', '01/07/2026', 'Luật có hiệu lực từ 01/07/2026; Luật HKDD năm 2006 hết hiệu lực kể từ ngày này.', 'ANSC 1.4, trang 4, 16: “…và chính thức có hiệu lực từ ngày 01/07/2026.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l4, 4, 3, 'Tàu bay chỉ được đăng ký quốc tịch Việt Nam khi nào?', '{"A": "Khi chưa có quốc tịch khác hoặc đã xóa quốc tịch nước ngoài", "B": "Khi đang mang quốc tịch nước ngoài", "C": "Khi chưa có giấy chứng nhận bay", "D": "Khi chưa có chủ sở hữu"}'::jsonb, 'A', 'Khi chưa có quốc tịch khác hoặc đã xóa quốc tịch nước ngoài', 'Chương II: tàu bay chỉ được đăng ký quốc tịch Việt Nam khi chưa có quốc tịch khác hoặc đã xóa quốc tịch nước ngoài.', 'ANSC 1.4, trang 6: “Tàu bay chỉ được đăng ký quốc tịch Việt Nam khi chưa có quốc tịch khác hoặc đã xóa quốc tịch nước ngoài.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l4, 4, 4, 'Người khai thác tàu bay phải có giấy tờ gì để được khai thác?', '{"A": "Giấy chứng nhận khai thác", "B": "Giấy phép lái xe", "C": "Giấy chứng nhận sức khỏe", "D": "Giấy phép thương mại"}'::jsonb, 'A', 'Giấy chứng nhận khai thác', 'Chương II: người khai thác tàu bay phải có giấy chứng nhận khai thác.', 'ANSC 1.4, trang 6: “Người khai thác tàu bay phải có giấy chứng nhận khai thác; người khai thác nước ngoài chỉ được công nhận khi đáp ứng quy định ICAO.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l4, 4, 5, 'Biện pháp quản lý đặc biệt có thể áp dụng đối với chuyến bay vi phạm là gì?', '{"A": "Đình chỉ chuyến bay hoặc yêu cầu hạ cánh", "B": "Cho phép bay tự do", "C": "Chỉ cảnh báo bằng văn bản", "D": "Không có biện pháp nào"}'::jsonb, 'A', 'Đình chỉ chuyến bay hoặc yêu cầu hạ cánh', 'Biện pháp quản lý đặc biệt gồm: đình chỉ chuyến bay, yêu cầu hạ cánh, bắt giữ tàu bay theo quyết định của Tòa án.', 'ANSC 1.4, trang 6–7: “Đình chỉ chuyến bay khi có dấu hiệu vi phạm an toàn, an ninh hoặc quốc phòng. Yêu cầu hạ cánh khi chuyến bay có dấu hiệu uy hiếp an toàn, an ninh.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l4, 4, 6, 'Người thứ ba ở mặt đất bị thiệt hại do tàu bay gây ra có quyền gì?', '{"A": "Yêu cầu bồi thường", "B": "Chỉ được báo cáo", "C": "Không có quyền gì", "D": "Chỉ được hỗ trợ y tế"}'::jsonb, 'A', 'Yêu cầu bồi thường', 'Chương VI: người thứ ba ở mặt đất bị thiệt hại do tàu bay đang bay hoặc vật rơi từ tàu bay có quyền yêu cầu bồi thường.', 'ANSC 1.4, trang 11: “Người thứ ba ở mặt đất bị thiệt hại do tàu bay đang bay hoặc vật từ tàu bay rơi xuống có quyền yêu cầu bồi thường.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l4, 4, 7, 'Quy định về cưỡng chế tàu bay vi phạm trong Chương IV cho thấy điều gì về cách tiếp cận của Luật 2026?', '{"A": "Đặt an toàn và an ninh quốc gia lên hàng đầu", "B": "Chỉ xử lý bằng biện pháp dân sự", "C": "Cho phép tàu bay tự do hoạt động", "D": "Loại bỏ quyền kiểm soát của quốc gia"}'::jsonb, 'A', 'Đặt an toàn và an ninh quốc gia lên hàng đầu', 'Chương IV cho phép bay chặn, bay kèm, ép hạ cánh tàu bay vi phạm, nhằm bảo đảm an toàn, an ninh, cho thấy Luật đặt an toàn và an ninh quốc gia lên hàng đầu.', 'ANSC 1.4, trang 8: “Chương IV thiết lập khung pháp lý… nhằm đảm bảo an toàn, an ninh và hiệu quả… Tàu bay vi phạm quy định có thể bị áp dụng biện pháp: bay chặn, bay kèm, ép hạ cánh hoặc các biện pháp cưỡng chế khác.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l4, 4, 8, 'Nghị định số 215/2026/NĐ-CP về an ninh hàng không thay thế văn bản nào?', '{"A": "Nghị định 92/2015/NĐ-CP", "B": "Nghị định 66/2015/NĐ-CP", "C": "Nghị định 75/2007/NĐ-CP", "D": "Nghị định 125/2015/NĐ-CP"}'::jsonb, 'A', 'Nghị định 92/2015/NĐ-CP', 'Nghị định 215/2026/NĐ-CP về an ninh hàng không thay thế Nghị định 92/2015/NĐ-CP.', 'ANSC 1.4, trang 17: “Nghị định số 215/2026/NĐ-CP ngày 18.06.2026 về an ninh hàng không có hiệu lực từ 01/7/2026 thay thế Nghị định 92/2015/NĐ-CP về an ninh hàng không.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l4, 4, 9, 'Nghị định số 221/2026/NĐ-CP về nhà chức trách hàng không và quản lý an toàn thay thế quy định nào?', '{"A": "Nghị định 66/2015/NĐ-CP", "B": "Nghị định 205/2023/NĐ-CP", "C": "Nghị định 208/2016/NĐ-CP", "D": "Nghị định 223/2021/NĐ-CP"}'::jsonb, 'A', 'Nghị định 66/2015/NĐ-CP', 'Nghị định 221/2026/NĐ-CP thay thế Nghị định 66/2015/NĐ-CP về nhà chức trách hàng không (cùng một số nghị định khác).', 'ANSC 1.4, trang 17: “Nghị định 221/2026/ND-CP… về nhà chức trách hàng không và quản lý an toàn… thay thế cho quy định tại các Nghị định 66/2015/ND-CP ngày 12/8/2015 về nhà chức trách hàng không.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l4, 4, 10, 'Chương 9 của Luật Hàng không dân dụng Việt Nam quy định về vấn đề gì?', '{"A": "An ninh hàng không", "B": "Vận tải hàng không", "C": "Nhân viên hàng không", "D": "Cảng hàng không"}'::jsonb, 'A', 'An ninh hàng không', 'Chương 9 (Chương IX) của Luật quy định về An ninh hàng không, từ điều 91 đến 98.', 'ANSC 1.4, trang 13, 18: “…trong đó tập trung nhất có Chương 9 quy định về An ninh hàng không từ điều 91 đến 98.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l4, 4, 11, 'Nghị định số 215/2026/NĐ-CP tập trung vào nội dung nào?', '{"A": "Phòng ngừa, ngăn chặn và xử lý hành vi can thiệp bất hợp pháp", "B": "Quản lý giá vé máy bay", "C": "Quy định về bảo hiểm hàng không", "D": "Quản lý nhân viên hàng không"}'::jsonb, 'A', 'Phòng ngừa, ngăn chặn và xử lý hành vi can thiệp bất hợp pháp', 'Nghị định 215/2026/NĐ-CP tập trung vào phòng ngừa, ngăn chặn và xử lý hành vi can thiệp bất hợp pháp.', 'ANSC 1.4, trang 19: “…tập trung vào việc phòng ngừa, ngăn chặn và xử lý các hành vi can thiệp bất hợp pháp trong hoạt động hàng không dân dụng.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l4, 4, 12, 'Lực lượng nào giữ vai trò nòng cốt trong công tác an ninh hàng không theo Nghị định 215/2026/NĐ-CP?', '{"A": "Công an", "B": "Hải quan", "C": "Bộ Xây dựng", "D": "Doanh nghiệp hàng không"}'::jsonb, 'A', 'Công an', 'Theo nguyên tắc chung của Nghị định 215, công tác an ninh hàng không là trách nhiệm của mọi tổ chức, cá nhân; lực lượng Công an giữ vai trò nòng cốt.', 'ANSC 1.4, trang 19: “Công tác an ninh hàng không là trách nhiệm của tất cả tổ chức, cá nhân; lực lượng Công an giữ vai trò nòng cốt.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l4, 4, 13, 'Cơ quan nào được xác định là Nhà chức trách an ninh hàng không Việt Nam?', '{"A": "Cục Quản lý xuất nhập cảnh – Bộ Công an", "B": "Bộ Quốc phòng", "C": "UBND tỉnh", "D": "Bộ Giao thông Vận tải"}'::jsonb, 'A', 'Cục Quản lý xuất nhập cảnh – Bộ Công an', 'Nhà chức trách an ninh hàng không Việt Nam là Cục Quản lý xuất nhập cảnh – Bộ Công an.', 'ANSC 1.4, trang 19: “Xác định rõ vai trò của Nhà chức trách an ninh hàng không Việt Nam (Cục Quản lý xuất nhập cảnh – Bộ Công an).”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l4, 4, 14, 'Người, phương tiện ra vào hoạt động tại khu vực hạn chế tại cảng hàng không phải có gì?', '{"A": "Thẻ hoặc giấy phép kiểm soát an ninh", "B": "Vé máy bay", "C": "Giấy chứng nhận sức khỏe", "D": "Giấy phép lái xe"}'::jsonb, 'A', 'Thẻ hoặc giấy phép kiểm soát an ninh', 'Người, phương tiện ra vào khu vực hạn chế phải có thẻ, giấy phép kiểm soát an ninh và chịu soi chiếu, giám sát.', 'ANSC 1.4, trang 19, 23: “Người, phương tiện ra vào khu vực hạn chế phải có thẻ, giấy phép kiểm soát an ninh và chịu soi chiếu, giám sát.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l4, 4, 15, 'Thông tư số 115/2026/TT-BCA quy định về vấn đề gì?', '{"A": "Thẻ, giấy phép, chứng nhận an ninh hàng không", "B": "Giá vé máy bay", "C": "Vận tải hàng hóa nguy hiểm", "D": "Bảo hiểm hàng không"}'::jsonb, 'A', 'Thẻ, giấy phép, chứng nhận an ninh hàng không', 'Thông tư 115/2026/TT-BCA quy định về thẻ, giấy phép, chứng nhận an ninh hàng không.', 'ANSC 1.4, trang 20: “Thông tư số 115/2026/TT-BCA Quy định về thẻ, giấy phép, chứng nhận an ninh hàng không.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l5, 5, 1, 'Kế hoạch An toàn hàng không toàn cầu (GASP) của ICAO có mục tiêu chính là gì?', '{"A": "Tăng số lượng chuyến bay thương mại", "B": "Giảm chi phí vận hành của hãng hàng không", "C": "Liên tục giảm thiểu thương vong và nguy cơ tai nạn", "D": "Phát triển động cơ đẩy mới cho tàu bay"}'::jsonb, 'C', 'Liên tục giảm thiểu thương vong và nguy cơ tai nạn', 'Mục đích của GASP là liên tục giảm thiểu thương vong và nguy cơ thương vong liên quan đến tai nạn.', 'ANSC 1.5, trang 4: “Mục đích của GASP là liên tục giảm thiểu thương vong và nguy cơ thương vong liên quan đến tai nạn bằng cách hướng dẫn việc phát triển và thực hiện hài hòa các kế hoạch an toàn hàng không khu vực và quốc gia.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l5, 5, 2, 'Theo định nghĩa của ICAO trong Phụ lục 19, “an toàn” trong hàng không được hiểu là gì?', '{"A": "Trạng thái không có rủi ro", "B": "Trạng thái rủi ro được giảm thiểu và kiểm soát ở mức chấp nhận được", "C": "Trạng thái loại bỏ hoàn toàn mọi yếu tố bất định", "D": "Trạng thái chỉ tập trung vào hoạt động bay"}'::jsonb, 'B', 'Trạng thái rủi ro được giảm thiểu và kiểm soát ở mức chấp nhận được', 'Phụ lục 19 định nghĩa an toàn là trạng thái rủi ro được giảm thiểu và kiểm soát đến mức chấp nhận được, không phải trạng thái "không có rủi ro".', 'ANSC 1.5, trang 4: “An toàn là trạng thái mà các rủi ro liên quan đến hoạt động hàng không… được giảm thiểu và kiểm soát đến mức chấp nhận được.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l5, 5, 3, 'Hệ thống quản lý an toàn (SMS) cụ thể hóa định nghĩa “An toàn” bằng cách nào?', '{"A": "Loại bỏ hoàn toàn mọi nguy cơ", "B": "Nhận diện, đánh giá và kiểm soát rủi ro", "C": "Tập trung vào đào tạo phi công", "D": "Giảm chi phí vận hành của hãng hàng không"}'::jsonb, 'B', 'Nhận diện, đánh giá và kiểm soát rủi ro', 'SMS cụ thể hóa định nghĩa an toàn qua ba bước: nhận diện rủi ro, đánh giá rủi ro, kiểm soát rủi ro.', 'ANSC 1.5, trang 5: “SMS cụ thể hóa định nghĩa "An toàn". Nhận diện rủi ro (Hazard Identification)… Đánh giá rủi ro (Risk Assessment)… Kiểm soát rủi ro (Risk Mitigation)…”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l5, 5, 4, 'Trong quản lý không lưu, biện pháp nào được coi là kiểm soát rủi ro để đảm bảo mức chấp nhận được?', '{"A": "Cho phép bay khi có lỗi kỹ thuật nhỏ", "B": "Phân cách tối thiểu giữa các tàu bay", "C": "Tăng số lượng chuyến bay thương mại", "D": "Giảm chi phí bảo dưỡng tàu bay"}'::jsonb, 'B', 'Phân cách tối thiểu giữa các tàu bay', 'Ví dụ trong tài liệu: phân cách tối thiểu giữa các tàu bay là biện pháp kiểm soát rủi ro trong quản lý không lưu.', 'ANSC 1.5, trang 4: “Trong quản lý không lưu, việc phân cách tối thiểu giữa các tàu bay là một biện pháp kiểm soát rủi ro, đảm bảo nguy cơ va chạm được giữ ở mức chấp nhận được.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l5, 5, 5, 'ICAO định nghĩa chương trình an toàn quốc gia là gì?', '{"A": "Bộ quy trình nội bộ của hãng hàng không", "B": "Tập hợp các quy định và hoạt động tích hợp nhằm cải thiện an toàn", "C": "Hệ thống quản lý tài chính của ngành hàng không", "D": "Công cụ giám sát của Cục Hàng không"}'::jsonb, 'B', 'Tập hợp các quy định và hoạt động tích hợp nhằm cải thiện an toàn', 'ICAO định nghĩa SSP là tập hợp các quy định và hoạt động tích hợp nhằm cải thiện an toàn.', 'ANSC 1.5, trang 5: “Định nghĩa của ICAO Chương trình an toàn quốc gia (SSP) là một tập hợp các quy định và hoạt động tích hợp nhằm mục đích cải thiện an toàn.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l5, 5, 6, 'Ai chịu trách nhiệm thiết lập và duy trì chương trình an toàn quốc gia ở Việt Nam?', '{"A": "Bộ Giao thông vận tải", "B": "Bộ Xây dựng", "C": "Cục Hàng không Việt Nam", "D": "ICAO"}'::jsonb, 'C', 'Cục Hàng không Việt Nam', 'Cục Hàng không Việt Nam là nhà chức trách hàng không, có trách nhiệm xây dựng, thực hiện, duy trì Chương trình an toàn HKDD Việt Nam.', 'ANSC 1.5, trang 8: “Cục Hàng không Việt Nam là Nhà chức trách hàng không Việt Nam có trách nhiệm xây dựng, tổ chức thực hiện, duy trì, rà soát và cập nhật Chương trình an toàn hàng không dân dụng Việt Nam.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l5, 5, 7, 'Điều tra tai nạn và sự cố trong chương trình an toàn quốc gia có mục tiêu chính là gì?', '{"A": "Xác định lỗi của cá nhân", "B": "Ngăn ngừa tai nạn và sự cố", "C": "Giảm chi phí bảo dưỡng", "D": "Tăng số lượng chuyến bay"}'::jsonb, 'B', 'Ngăn ngừa tai nạn và sự cố', 'Điều tra tai nạn, sự cố có mục tiêu duy nhất là ngăn ngừa, không nhằm phân bổ trách nhiệm hay lỗi.', 'ANSC 1.5, trang 6: “Nhà nước phải thiết lập một quy trình điều tra tai nạn và sự cố độc lập, với mục tiêu duy nhất là ngăn ngừa tai nạn và sự cố, chứ không phải là phân bổ trách nhiệm hay lỗi lầm.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l5, 5, 8, 'Chương trình an toàn quốc gia yêu cầu các nhà cung cấp dịch vụ nào phải triển khai hệ thống quản lý an toàn?', '{"A": "Chỉ các hãng hàng không", "B": "Chỉ các sân bay", "C": "Các tổ chức đào tạo, khai thác, bảo dưỡng, thiết kế, sản xuất, ATS, sân bay", "D": "Các cơ quan quản lý nhà nước"}'::jsonb, 'C', 'Các tổ chức đào tạo, khai thác, bảo dưỡng, thiết kế, sản xuất, ATS, sân bay', 'SSP yêu cầu các nhà cung cấp dịch vụ triển khai SMS gồm: tổ chức đào tạo, nhà khai thác tàu bay, tổ chức bảo dưỡng, tổ chức thiết kế/sản xuất, nhà cung cấp dịch vụ ATS, nhà khai thác cảng hàng không, sân bay.', 'ANSC 1.5, trang 5–6: “(i) Các tổ chức đào tạo… (ii) Các nhà khai thác tàu bay… (iii) Các tổ chức bảo dưỡng… (iv) Các tổ chức chịu trách nhiệm thiết kế kiểu loại hoặc sản xuất tàu bay (v) Các nhà cung cấp dịch vụ kiểm soát không lưu (ATS) (vi) Các nhà khai thác cảng hàng không, sân bay.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l5, 5, 9, 'Một trong các nội dung thúc đẩy an toàn quốc gia trong Chương trình an toàn quốc là gì?', '{"A": "Đào tạo và truyền thông an toàn", "B": "Giảm chi phí vận hành", "C": "Tăng số lượng chuyến bay", "D": "Phát triển động cơ mới"}'::jsonb, 'A', 'Đào tạo và truyền thông an toàn', 'Thành phần "Thúc đẩy an toàn quốc gia" của SSP gồm đào tạo, truyền thông và phổ biến thông tin an toàn.', 'ANSC 1.5, trang 8: “(4) Thúc đẩy an toàn quốc gia – Đào tạo nội bộ, truyền thông và phổ biến thông tin an toàn.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l5, 5, 10, 'Hệ thống quản lý an toàn của doanh nghiệp hàng không được ICAO coi là gì?', '{"A": "Công cụ quản lý tài chính", "B": "Xương sống của hệ thống an toàn", "C": "Bộ quy trình đào tạo phi công", "D": "Hệ thống quản lý nhân sự"}'::jsonb, 'B', 'Xương sống của hệ thống an toàn', 'SMS được tài liệu gọi là "xương sống" của hệ thống an toàn trong ngành hàng không hiện đại.', 'ANSC 1.5, trang 14: “Nói cách khác, SMS chính là "xương sống" của hệ thống an toàn trong ngành hàng không hiện đại.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l5, 5, 11, 'Nội dung tối thiểu của hệ thống quản lý an toàn phải bao gồm gì?', '{"A": "Nhận diện mối nguy, biện pháp khắc phục, giám sát liên tục", "B": "Quản lý tài chính, nhân sự, đào tạo", "C": "Giảm chi phí và tăng lợi nhuận", "D": "Tăng số lượng chuyến bay"}'::jsonb, 'A', 'Nhận diện mối nguy, biện pháp khắc phục, giám sát liên tục', 'Nội dung SMS tối thiểu gồm: xác định mối nguy và đánh giá rủi ro; biện pháp khắc phục; giám sát liên tục và đánh giá thường xuyên.', 'ANSC 1.5, trang 11–12: “i) Quy trình xác định các mối nguy hiểm về an toàn… ii) Quy trình phát triển và thực hiện các biện pháp khắc phục… iii) Quy định về việc giám sát liên tục và đánh giá thường xuyên…”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l5, 5, 12, 'Cơ quan nào chịu trách nhiệm xây dựng và thực hiện Chương trình an toàn hàng không dân dụng Việt Nam?', '{"A": "Bộ Giao thông Vận tải", "B": "Bộ Xây dựng", "C": "Cục Hàng không Việt Nam", "D": "ICAO"}'::jsonb, 'C', 'Cục Hàng không Việt Nam', 'Theo Nghị định 221/2026/NĐ-CP, Cục Hàng không Việt Nam có trách nhiệm xây dựng và tổ chức thực hiện Chương trình an toàn HKDD Việt Nam.', 'ANSC 1.5, trang 8: “Cục Hàng không Việt Nam là Nhà chức trách hàng không Việt Nam có trách nhiệm xây dựng, tổ chức thực hiện, duy trì, rà soát và cập nhật Chương trình an toàn hàng không dân dụng Việt Nam.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l5, 5, 13, 'Mục tiêu cao nhất trong mọi hoạt động hàng không theo Chương trình an toàn hàng không là gì?', '{"A": "Hiệu quả kinh tế", "B": "An toàn", "C": "Phát triển bền vững", "D": "Hợp tác quốc tế"}'::jsonb, 'B', 'An toàn', 'Chính sách an toàn trong Chương trình (Thông tư 18/2026/TT-BXD) xác định an toàn là mục tiêu cao nhất.', 'ANSC 1.5, trang 10: “An toàn là mục tiêu cao nhất trong mọi hoạt động hàng không.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l5, 5, 14, 'Một trong những nội dung thúc đẩy an toàn hàng không là gì?', '{"A": "Giảm chi phí vận hành", "B": "Khuyến khích báo cáo an toàn tự nguyện", "C": "Tăng số lượng chuyến bay", "D": "Mở rộng thị trường quốc tế"}'::jsonb, 'B', 'Khuyến khích báo cáo an toàn tự nguyện', 'Một trong các nội dung thúc đẩy an toàn là khuyến khích báo cáo an toàn tự nguyện, xây dựng văn hóa an toàn.', 'ANSC 1.5, trang 10: “Khuyến khích báo cáo an toàn tự nguyện, xây dựng văn hóa an toàn.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l5, 5, 15, 'Theo ICAO, mỗi sân bay phải thiết lập kế hoạch ứng phó khẩn cấp nhằm đối phó với những tình huống nào?', '{"A": "Chỉ tai nạn tàu bay", "B": "Chỉ hỏa hoạn và thiên tai", "C": "Các sự cố tàu bay, phá hoại, hàng hóa nguy hiểm, hỏa hoạn, thiên tai, dịch bệnh", "D": "Chỉ hành vi can thiệp bất hợp pháp"}'::jsonb, 'C', 'Các sự cố tàu bay, phá hoại, hàng hóa nguy hiểm, hỏa hoạn, thiên tai, dịch bệnh', 'Phụ lục 14 yêu cầu kế hoạch ứng phó khẩn cấp sân bay bao quát nhiều tình huống: sự cố tàu bay, phá hoại, hàng hóa nguy hiểm, hỏa hoạn, thiên tai, khẩn cấp sức khỏe cộng đồng (dịch bệnh).', 'ANSC 1.5, trang 21: “Các trường hợp khẩn cấp như là sự cố tàu bay, phá hoại bao gồm cả đe dọa đánh bom, tàu bay bị chiếm giữ trái phép, sự cố liên quan đến hàng hóa nguy hiểm, hỏa hoạn, thiên tai và các trường hợp khẩn cấp về sức khỏe cộng đồng…”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l6, 6, 1, 'Hành khách quốc tế phải thực hiện thủ tục nào trước khi vào khu cách ly?', '{"A": "Kiểm tra an ninh và xuất nhập cảnh", "B": "Kiểm tra vé điện tử", "C": "Kiểm tra hành lý ký gửi", "D": "Kiểm tra sức khỏe"}'::jsonb, 'A', 'Kiểm tra an ninh và xuất nhập cảnh', 'Hành khách quốc tế phải qua kiểm tra soi chiếu an ninh và thủ tục xuất cảnh rồi mới vào khu cách ly.', 'ANSC 1.6, trang 6–7: “Sau khi hoàn tất kiểm tra soi chiếu và xuất cảnh hành khách vào khu vực phòng chờ (khu cách ly).”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l6, 6, 2, 'Thời điểm đóng cửa tàu bay thường diễn ra khi nào?', '{"A": "30 phút trước giờ cất cánh", "B": "20 phút trước giờ cất cánh", "C": "15 phút trước giờ cất cánh", "D": "10 phút trước giờ cất cánh"}'::jsonb, 'C', '15 phút trước giờ cất cánh', 'Việc đóng cửa tàu bay thường thực hiện không quá 15 phút trước giờ cất cánh.', 'ANSC 1.6, trang 7: “Việc đóng cửa tàu bay thường thực hiện không quá 15 phút trước giờ cất cánh.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l6, 6, 3, 'Hành khách cần hỗ trợ đặc biệt (UM, khuyết tật, phụ nữ có thai) phải thông báo từ giai đoạn nào?', '{"A": "Khi làm thủ tục check-in", "B": "Khi boarding", "C": "Khi đặt chỗ", "D": "Khi nhận hành lý"}'::jsonb, 'C', 'Khi đặt chỗ', 'Hành khách cần hỗ trợ đặc biệt phải thông báo từ khâu đặt chỗ để hãng chuẩn bị.', 'ANSC 1.6, trang 7: “Hành khách cần sự hỗ trợ đặc biệt (UM - trẻ em đi một mình, hành khách khuyết tật, phụ nữ có thai) cần thông báo từ khâu đặt chỗ để hãng chuẩn bị.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l6, 6, 4, 'Hãng hàng không chịu trách nhiệm pháp lý cao nhất đối với hành khách và hành lý dựa trên cơ sở nào?', '{"A": "Quy định của ICAO", "B": "Hợp đồng vận chuyển (vé máy bay)", "C": "Quy định của hải quan", "D": "Quy định của an ninh sân bay"}'::jsonb, 'B', 'Hợp đồng vận chuyển (vé máy bay)', 'Trách nhiệm pháp lý cao nhất của hãng hàng không dựa trên hợp đồng vận chuyển (vé máy bay).', 'ANSC 1.6, trang 8: “Hãng hàng không là bên chịu trách nhiệm pháp lý cao nhất đối với hành khách và hành lý dựa trên hợp đồng vận chuyển (vé máy bay).”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l6, 6, 5, 'Hành khách có nghĩa vụ gì để đảm bảo an ninh, an toàn chung?', '{"A": "Chỉ cần mua vé đầy đủ", "B": "Tuân thủ điều lệ vận chuyển và khai báo trung thực hành lý", "C": "Không cần chuẩn bị giấy tờ tùy thân", "D": "Chỉ cần có mặt tại sân bay"}'::jsonb, 'B', 'Tuân thủ điều lệ vận chuyển và khai báo trung thực hành lý', 'Hành khách có nghĩa vụ tuân thủ điều lệ vận chuyển và khai báo trung thực về hành lý.', 'ANSC 1.6, trang 8: “Hành khách là chủ thể sử dụng dịch vụ, có nghĩa vụ tuân thủ các điều lệ vận chuyển để đảm bảo an ninh, an toàn chung. … Khai báo trung thực về hành lý mang theo.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l6, 6, 6, 'Đơn vị phục vụ mặt đất (GHA) có nhiệm vụ nào sau đây?', '{"A": "Cấp phép bay", "B": "Làm thủ tục check-in và xử lý hành lý", "C": "Kiểm tra hộ chiếu, thị thực", "D": "Giám sát an ninh hàng không"}'::jsonb, 'B', 'Làm thủ tục check-in và xử lý hành lý', 'GHA phục vụ hành khách (check-in, cấp thẻ lên tàu bay) và phục vụ hành lý. Kiểm tra hộ chiếu là việc của Công an cửa khẩu; giám sát an ninh là việc của lực lượng ANHK.', 'ANSC 1.6, trang 8: “Nhiệm vụ phục vụ hành khách (Passenger Services) là làm thủ tục check-in… Nhiệm vụ phục vụ hành lý (Baggage Services) là tiếp nhận hành lý từ quầy check-in…”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l6, 6, 7, 'Cơ quan nào chịu trách nhiệm giám sát an toàn, cấp phép bay và xử phạt hãng vi phạm nghĩa vụ với hành khách?', '{"A": "Hải quan", "B": "Công an cửa khẩu", "C": "Cảng vụ hàng không / Cục Hàng không", "D": "An ninh hàng không"}'::jsonb, 'C', 'Cảng vụ hàng không / Cục Hàng không', 'Cảng vụ hàng không / Cục Hàng không giám sát an toàn, cấp phép bay, xử phạt hãng vi phạm nghĩa vụ với hành khách.', 'ANSC 1.6, trang 9: “Cảng vụ hàng không / Cục Hàng không… Có trách nhiệm giám sát an toàn… cấp phép bay. … Giám sát và xử phạt các hãng hàng không vi phạm nghĩa vụ đối với hành khách khi xảy ra chậm, hủy chuyến.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l6, 6, 8, 'Lực lượng an ninh hàng không có nhiệm vụ chính là gì?', '{"A": "Bán vé cho hành khách", "B": "Kiểm tra, soi chiếu, lục soát và ngăn chặn hành vi can thiệp bất hợp pháp", "C": "Cấp hộ chiếu cho hành khách", "D": "Quản lý hệ thống đặt chỗ"}'::jsonb, 'B', 'Kiểm tra, soi chiếu, lục soát và ngăn chặn hành vi can thiệp bất hợp pháp', 'Lực lượng ANHK chịu trách nhiệm kiểm tra, soi chiếu, lục soát, giám sát và ngăn chặn hành vi can thiệp bất hợp pháp.', 'ANSC 1.6, trang 9: “Lực lượng An ninh hàng không… chịu trách nhiệm kiểm tra, soi chiếu, lục soát, giám sát an ninh hàng không đối với hành khách và hành lý… ngăn chặn đối phó với các hành vi can thiệp bất hợp pháp.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l6, 6, 9, 'Trong chuyến bay quốc tế, cơ quan nào kiểm soát nghĩa vụ thuế đối với hành lý hành khách mang theo?', '{"A": "Công an cửa khẩu", "B": "Hải quan", "C": "Kiểm dịch y tế", "D": "Cục Hàng không"}'::jsonb, 'B', 'Hải quan', 'Hải quan kiểm soát nghĩa vụ thuế đối với hành lý hành khách mang theo.', 'ANSC 1.6, trang 9: “Hải quan (Customs) kiểm soát nghĩa vụ thuế đối với hành lý hành khách mang theo; ngăn chặn buôn lậu, vận chuyển ngoại tệ vượt quá quy định.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l6, 6, 10, 'Vận đơn hàng không (Air Waybill – AWB) được phát hành ở giai đoạn nào của quy trình quốc tế?', '{"A": "Giai đoạn chuẩn bị và đặt chỗ", "B": "Giai đoạn thủ tục hải quan", "C": "Giai đoạn vận chuyển và nhận hàng", "D": "Giai đoạn kiểm tra an ninh"}'::jsonb, 'C', 'Giai đoạn vận chuyển và nhận hàng', 'Trong quy trình quốc tế, việc "Phát hành AWB" được liệt kê ở Giai đoạn 3 – Vận chuyển và nhận hàng.', 'ANSC 1.6, trang 11: “c) Giai đoạn 3 - Vận chuyển và nhận hàng (Linehaul & Destination). Phát hành AWB: Hãng hàng không hoặc đại lý phát hành vận đơn.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l6, 6, 11, 'Trong quy trình nội địa, hàng hóa phải qua kiểm tra nào trước khi cấp vận đơn?', '{"A": "Kiểm tra vé máy bay", "B": "Kiểm tra soi chiếu X-ray an ninh", "C": "Kiểm tra giấy tờ tùy thân", "D": "Kiểm tra sức khỏe"}'::jsonb, 'B', 'Kiểm tra soi chiếu X-ray an ninh', 'Trong quy trình nội địa, hàng hóa phải qua máy soi chiếu X-ray trước khi được gắn mã vận đơn (AWB).', 'ANSC 1.6, trang 11: “Kiểm tra an ninh và đóng gói cấp vận đơn hàng không: Hàng hóa phải qua được soi chiếu qua máy soi chiếu X-ray để phát hiện vật cấm chất nổ.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l6, 6, 12, 'Hàng hóa nội địa được chất xếp lên thiết bị tiêu chuẩn nào trước khi đưa vào khoang hàng tàu bay?', '{"A": "Container đường biển", "B": "ULD (Unit Load Device)", "C": "Xe tải chuyên dụng", "D": "Pallet gỗ thô"}'::jsonb, 'B', 'ULD (Unit Load Device)', 'Hàng được chất xếp lên ULD (thùng hoặc pallet tiêu chuẩn) trước khi đưa vào khoang hàng.', 'ANSC 1.6, trang 12: “Nhân viên chất xếp hàng lên ULD (Unit Load Device) các thùng hoặc pallet tiêu chuẩn để đưa vào khoang hàng của tàu bay.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l6, 6, 13, 'Quy trình vận chuyển hàng hóa nội địa bằng đường hàng không đặc biệt hữu ích cho loại hàng nào?', '{"A": "Hàng hóa giá trị thấp", "B": "Hàng hóa dễ hỏng, giá trị cao, cần giao nhanh", "C": "Hàng hóa cồng kềnh không thể vận chuyển", "D": "Hàng hóa không cần kiểm tra an ninh"}'::jsonb, 'B', 'Hàng hóa dễ hỏng, giá trị cao, cần giao nhanh', 'Quy trình nội địa đặc biệt hữu ích cho hàng giá trị cao, dễ hỏng hoặc cần giao nhanh.', 'ANSC 1.6, trang 12: “…đặc biệt hữu ích cho hàng hóa giá trị cao, dễ hỏng hoặc cần giao nhanh.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l6, 6, 14, 'Người gửi hàng (Shipper/Consignor) chịu trách nhiệm pháp lý cao nhất về điều gì?', '{"A": "Lịch trình bay", "B": "Tính trung thực, an toàn và hợp pháp của lô hàng", "C": "Thuế nhập khẩu", "D": "Phí lưu kho"}'::jsonb, 'B', 'Tính trung thực, an toàn và hợp pháp của lô hàng', 'Người gửi hàng chịu trách nhiệm pháp lý cao nhất về tính trung thực, an toàn và hợp pháp của lô hàng.', 'ANSC 1.6, trang 12: “Người gửi hàng chịu trách nhiệm pháp lý cao nhất về tính trung thực, an toàn và hợp pháp của lô hàng trước khi đưa lên máy bay.”', true);
  insert into public.questions (set_id, lesson_id, lesson_num, question_order, question_text, options, correct_option, answer_text, explanation, source_ref, is_active) values (v_set_id, v_l6, 6, 15, 'An ninh hàng không thực hiện kiểm tra hàng hóa bằng phương tiện nào?', '{"A": "Máy soi chiếu X-quang", "B": "Máy đo trọng lượng", "C": "Máy kiểm tra nhiệt độ", "D": "Máy kiểm tra độ ẩm"}'::jsonb, 'A', 'Máy soi chiếu X-quang', 'An ninh hàng không kiểm tra hàng hóa bằng máy soi chiếu X-quang.', 'ANSC 1.6, trang 15: “Thực hiện soi chiếu bằng máy X-quang để phát hiện vũ khí, chất nổ, ma túy, hàng cấm.”', true);
